/**
 * Embedded sprite assets — Human faction Priority 1 set.
 *
 * Sprites are 256px PNGs embedded as data URIs (from Manus art integration).
 * The renderer uses these where available, falling back to procedural
 * shapes if a sprite fails to load. Total: ~223KB.
 *
 * Future factions extend SPRITES with their own keys; the renderer maps
 * entity kinds to sprite keys via spriteFor().
 */
const SPRITE_PEASANT: string = 'data:image/png;base64,'

const SPRITE_HOMESTEAD_FARM: string = 'data:image/png;base64,'

const SPRITE_TOWN_HALL_L1: string = 'data:image/png;base64,'

export const SPRITES: Record<string, string> = {
  peasant: SPRITE_PEASANT,
  homestead_farm: SPRITE_HOMESTEAD_FARM,
  town_hall_l1: SPRITE_TOWN_HALL_L1,
}

// Loaded image cache
const imageCache = new Map<string, HTMLImageElement>()
let loadStarted = false

/** Start loading all sprites (call once at startup). */
export function loadSprites(): void {
  if (loadStarted) return
  loadStarted = true
  for (const [key, uri] of Object.entries(SPRITES)) {
    const img = new Image()
    img.src = uri
    imageCache.set(key, img)
  }
}

/** Get a loaded sprite, or null if not yet ready. */
export function getSprite(key: string): HTMLImageElement | null {
  const img = imageCache.get(key)
  if (img && img.complete && img.naturalWidth > 0) return img
  return null
}

/**
 * Wait for all sprites to load (or fail), with a timeout.
 * Resolves when done; the game uses procedural fallbacks for any
 * sprite that didn't load in time. Keeps first paint fast.
 */
export function waitForSprites(timeoutMs = 2000): Promise<void> {
  loadSprites()
  const images = [...imageCache.values()]
  if (images.length === 0) return Promise.resolve()

  return new Promise((resolve) => {
    let done = 0
    const check = () => {
      done++
      if (done >= images.length) resolve()
    }
    const timer = setTimeout(resolve, timeoutMs)
    for (const img of images) {
      if (img.complete) {
        check()
      } else {
        img.onload = check
        img.onerror = check
      }
    }
    // Clear timeout when all done
    void timer
  })
}
